/* Relatórios somente de leitura, sem inicialização de bases nem migração. */
(()=>{'use strict';const R=MartinsRelatorios,J=MartinsJornada,P=MartinsPersistenciaRdo,$=id=>document.getElementById(id);if(!$('view-gestao'))return;
const style=document.createElement('style');style.textContent='#rp-warnings{white-space:pre-wrap;color:#92400e}#rp-drawer{padding:12px;border-top:1px solid #e2e8f0}#rp-drawer button{min-height:44px;width:100%;text-align:left;font-size:12px;font-weight:700;color:#334155}#view-relatorios table{min-width:850px}#view-relatorios [hidden]{display:none!important}#rp-status{white-space:pre-wrap;color:#92400e}@media print{#view-relatorios{display:none!important}}';document.head.append(style);
const panel=document.createElement('section');panel.id='view-relatorios';panel.className='mf-box hidden';panel.innerHTML='<h2>Relatórios</h2><p>Consulta dos registros locais do sistema. Não altera frequência, RDO, recibos ou saldos. A exportação leva as linhas do filtro e os avisos da consulta.</p><div class="mf-grid"><label>Relatório<select id="rp-type"></select></label><label id="rp-period-start">De<input id="rp-start" type="date"></label><label id="rp-period-end">Até<input id="rp-end" type="date"></label><label id="rp-work-label">Obra<select id="rp-work"></select></label><label id="rp-person-label">Colaborador<select id="rp-person"></select></label><label id="rp-source-label" hidden>Origem do estoque<select id="rp-source"><option value="">Materiais e uniformes / EPIs</option><option>Materiais</option><option>Uniformes / EPIs</option></select></label><label id="rp-category-label" hidden>Categoria<select id="rp-category"></select></label><label id="rp-stock-state-label" hidden>Situação do saldo<select id="rp-stock-state"><option value="">Todas</option><option>Normal</option><option>Sem saldo</option><option>Repor</option><option>Mínimo não informado</option><option>Conferir cadastro</option></select></label><label id="rp-search-label">Buscar item ou código<input id="rp-search" maxlength="200"></label></div><button type="button" id="rp-update">Atualizar relatório</button><button type="button" id="rp-export">Exportar CSV do filtro</button><p id="rp-status" role="status" aria-live="polite"></p><h3 id="rp-title"></h3><p id="rp-summary"></p><p id="rp-note"></p><p id="rp-warnings" role="status"></p><div class="mf-scroll"><table><thead id="rp-head"></thead><tbody id="rp-rows"></tbody></table></div>';$('view-gestao').after(panel);let current=null,snapshot=null,config=null;
const titles=[['mao_obra','Mão de obra'],['uniformes','Uniformes / EPIs entregues'],['estoque','Saldo atual de estoque']],today=()=>new Date().toLocaleDateString('en-CA');
function actor(){let session;try{session=JSON.parse(sessionStorage.getItem('cm_active_user')||'null');}catch{}const u=currentLoggedUser,id=x=>String(x?.id||x?.usuario||x?.email||'');if(!session||!id(u)||id(u)!==id(session)||session.perfil!==u.perfil||session.status==='Inativo'||!R.canView(u,$('rp-type').value))throw Error('Entre com perfil autorizado para este relatório.');}
function keys(type){return type==='mao_obra'?['cm_planejamento_integrado_v1','cm_frequencia_diaria_db','cm_gestao_rdo_v5_db','cm_colaboradores_db']:type==='uniformes'?[R.KEYS.deliveries,'cm_colaboradores_db']:[R.KEYS.products,R.KEYS.uniforms];}
function raw(){return Object.fromEntries(keys($('rp-type').value).map(k=>[k,localStorage.getItem(k)]));}
function filters(){return {type:$('rp-type').value,start:$('rp-start').value,end:$('rp-end').value,obra:$('rp-work').value,pessoa:$('rp-person').value,source:$('rp-source').value,category:$('rp-category').value,status:$('rp-stock-state').value,search:$('rp-search').value,today:today()};}
function opts(select,rows,label){const old=select.value;select.replaceChildren(new Option(label,''));for(const r of rows)select.add(new Option(typeof r==='string'?r:r.label,typeof r==='string'?r:r.value));if([...select.options].some(o=>o.value===old))select.value=old;}
function visibility(){const type=$('rp-type').value,stock=type==='estoque';for(const id of ['rp-period-start','rp-period-end','rp-work-label','rp-person-label'])$(id).hidden=stock;for(const id of ['rp-source-label','rp-category-label','rp-stock-state-label'])$(id).hidden=!stock;$('rp-search-label').hidden=type==='mao_obra';}
function build(f){if(f.type==='mao_obra')return R.labor({...f,plans:J.read(localStorage,'cm_planejamento_integrado_v1',[]),frequency:J.read(localStorage,'cm_frequencia_diaria_db',initialFrequenciaDb),rdos:J.read(localStorage,'cm_gestao_rdo_v5_db',initialRdos),employees:J.read(localStorage,'cm_colaboradores_db',initialColaboradores)});if(f.type==='uniformes')return R.deliveries({...f,rows:J.read(localStorage,R.KEYS.deliveries,initialDistribuicoes),employees:J.read(localStorage,'cm_colaboradores_db',initialColaboradores)});if(f.type==='estoque')return R.stock({...f,products:J.read(localStorage,R.KEYS.products,INITIAL_PRODUTOS_FATOR),uniforms:J.read(localStorage,R.KEYS.uniforms,initialEstoqueUniformes)});throw Error('Selecione um relatório disponível');}
function clear(){current=null;snapshot=null;config=null;$('rp-head').replaceChildren();$('rp-rows').replaceChildren();for(const id of ['rp-title','rp-summary','rp-note','rp-warnings'])$(id).textContent='';}
function refresh(){clear();try{actor();P.guard(localStorage,J.KEYS.rdos);visibility();const before=raw();let f=filters(),report=build(f);if(f.type==='estoque')opts($('rp-category'),report.options.categories,'Todas as categorias');else{opts($('rp-work'),report.options.works,'Todas as obras');opts($('rp-person'),report.options.people,'Todos os colaboradores / históricos');}if(P.canonical(f)!==P.canonical(filters())){f=filters();report=build(f);}if(P.canonical(before)!==P.canonical(raw()))throw Error('Fontes alteradas durante a leitura. Atualize novamente.');for(const [key,value] of Object.entries(before))if(value===null)report.warnings.push(key+': base ainda não gravada; consulta usa os valores iniciais disponíveis no aplicativo.');$('rp-title').textContent=report.title;$('rp-summary').textContent=report.summary;$('rp-note').textContent=report.note;$('rp-warnings').textContent=report.warnings.join('\n');const tr=document.createElement('tr');for(const text of report.headers){const th=document.createElement('th');th.textContent=text;tr.append(th);}$('rp-head').append(tr);for(const values of report.rows){const row=document.createElement('tr');for(const value of values){const td=document.createElement('td');td.textContent=typeof value==='number'?value.toLocaleString('pt-BR',{maximumFractionDigits:3}):String(value??'');row.append(td);}$('rp-rows').append(row);}if(!report.rows.length){const row=document.createElement('tr'),td=document.createElement('td');td.colSpan=report.headers.length;td.textContent='Nenhum registro neste filtro.';row.append(td);$('rp-rows').append(row);}current=report;snapshot=before;config=f;$('rp-status').textContent='Consulta gerada em '+new Date().toLocaleString('pt-BR')+' · '+report.rows.length+' linha(s).';}catch(e){$('rp-status').textContent='Relatório não gerado: '+e.message;}}
function open(){const old=$('rp-type').value;$('rp-type').replaceChildren();for(const [key,label] of titles)if(R.canView(typeof currentLoggedUser==='undefined'?null:currentLoggedUser,key))$('rp-type').add(new Option(label,key));if([...$('rp-type').options].some(o=>o.value===old))$('rp-type').value=old;visibility();refresh();}
$('rp-type').onchange=()=>{for(const id of ['rp-work','rp-person','rp-category'])$(id).replaceChildren();$('rp-search').value='';refresh();};$('rp-update').onclick=refresh;for(const id of ['rp-start','rp-end','rp-work','rp-person','rp-source','rp-category','rp-stock-state'])$(id).onchange=refresh;$('rp-search').oninput=()=>{current=null;$('rp-status').textContent='Busca alterada. Atualize o relatório para consultar e exportar.';};
$('rp-export').onclick=()=>{try{actor();P.guard(localStorage,J.KEYS.rdos);if(!current||P.canonical(filters())!==P.canonical(config)||P.canonical(raw())!==P.canonical(snapshot))throw Error('Filtros ou registros mudaram. Atualize antes de exportar.');const url=URL.createObjectURL(new Blob([R.csv(current)],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='martins-relatorio-'+current.type+'-'+today()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);$('rp-status').textContent='CSV preparado com '+current.rows.length+' linha(s) do filtro.';}catch(e){$('rp-status').textContent=e.message;}};
const oldNav=window.navegarParaSecao;window.navegarParaSecao=function(name,sub){if(name==='relatorios'){oldNav(name);panel.classList.remove('hidden');open();}else{panel.classList.add('hidden');oldNav(name,sub);}};const oldDrawerNav=window.navegarPeloDrawer;window.navegarPeloDrawer=function(name){if(name==='relatorios')return window.navegarParaSecao(name);return oldDrawerNav(name);};
function install(){if($('rp-drawer'))return;const list=$('drawer-menu-lateral')?.querySelector('.overflow-y-auto');if(!list)return;const box=document.createElement('div');box.id='rp-drawer';const b=document.createElement('button');b.type='button';b.id='rp-menu';b.textContent='📊 Relatórios: mão de obra, uniformes e estoque';b.onclick=()=>window.navegarParaSecao('relatorios');box.append(b);list.append(box);}const oldDrawer=window.reorganizarDrawerLateralDefinitivo;if(typeof oldDrawer==='function')window.reorganizarDrawerLateralDefinitivo=function(...args){const r=oldDrawer.apply(this,args);install();return r;};document.addEventListener('DOMContentLoaded',install);install();window.addEventListener('storage',e=>{if(keys($('rp-type').value).includes(e.key)&&!panel.classList.contains('hidden')){current=null;$('rp-status').textContent='Os registros mudaram em outra aba. Atualize o relatório.';}});const day=today();$('rp-start').value=day.slice(0,8)+'01';$('rp-end').value=day;$('rp-end').max=day;
})();
